      "define": "An algebraic structure is a set equipped with operations whose behavior is controlled by specified axioms.",
      "notes": "[Read concept note](./notes/Algebra_Structure.md)"
    },
    "Boolean_Algebra": {
      "title": "Boolean Algebra",
      "type": "Algebra",
      "define": "Boolean algebra is an algebraic structure that formalizes logical operations such as and, or, and not.",
      "notes": "[Read concept note](./notes/Boolean_Algebra.md)"
    },
    "Chain_Complex": {
      "title": "Chain Complex",
      "type": "Algebra",
      "define": "A chain complex is a sequence of modules or vector spaces linked by differentials whose successive composition is zero.",
      "notes": "[Read concept note](./notes/Chain_Complex.md)"
    },
    "Complex_Field": {
      "title": "Complex Field",
      "type": "Algebra",
      "define": "The complex field extends the real numbers by adjoining a square root of $-1$.",
      "notes": "[Read concept note](./notes/Complex_Field.md)"
    },
    "Cubic_Function": {
      "title": "Cubic Function",
      "type": "Algebra",
      "define": "A cubic function is a polynomial function whose highest-degree term has degree three.",
