    },
    "Differential_Manifold": {
      "title": "Differential Manifold",
      "type": "Geometry",
      "define": "A smooth manifold is a space that locally looks like $\\mathbb R^n$, and whose overlapping coordinate systems transform smoothly into one another.",
      "notes": "[Read concept note](./notes/Differential_Manifold.md)"
    },
    "Field": {
      "title": "Field",
      "type": "Algebra",
      "define": "A field is an algebraic structure where addition, subtraction, multiplication, and division by nonzero elements are all possible.",
      "notes": "[Read concept note](./notes/Field.md)"
    },
    "Fourth_Order_Function": {
      "title": "Fourth Order Function",
      "type": "Algebra",
      "define": "A fourth-order function is a polynomial function whose highest-degree term has degree four.",
      "notes": "[Read concept note](./notes/Fourth_Order_Function.md)"
    },
    "Function": {
      "title": "Function",
      "type": "Mathematical Logic and Foundations",
      "define": "A function assigns each input exactly one output.",
      "notes": "[Read concept note](./notes/Function.md)"
    },
    "Group": {
      "title": "Group",
      "type": "Algebra",
      "define": "A group is an algebraic structure that captures reversible composition with an identity element.",
      "notes": "[Read concept note](./notes/Group.md)"
    },
    "Inner_Product_Space": {
      "title": "Inner Product Space",
      "type": "Algebra",
      "define": "An inner product space is a vector space with a product that defines length, angle, and orthogonality.",
      "notes": "[Read concept note](./notes/Inner_Product_Space.md)"
    },
    "Lattice": {
      "title": "Lattice",
      "type": "Discrete Mathematics",
      "define": "A lattice is an ordered set in which every pair of elements has both a greatest lower bound and a least upper bound.",
      "notes": "[Read concept note](./notes/Lattice.md)"
    },
    "Lie_Algebra": {
      "title": "Lie Algebra",
      "type": "Algebra",
      "define": "A Lie algebra is a vector space equipped with a bilinear bracket satisfying antisymmetry and the Jacobi identity.",
      "notes": "[Read concept note](./notes/Lie_Algebra.md)"
    },
    "Lie_Group": {
      "title": "Lie Group",
      "type": "Algebra",
      "define": "A Lie group is a group whose operations vary smoothly with respect to a manifold structure.",
      "notes": "[Read concept note](./notes/Lie_Group.md)"
    },
    "Linear_Function": {
      "title": "Linear Function",
      "type": "Algebra",
      "define": "A linear function preserves addition and scalar multiplication.",
      "notes": "[Read concept note](./notes/Linear_Function.md)"
    },
    "Linear_Space": {
      "title": "Linear Space",
      "type": "Algebra",
      "define": "A linear space is a set whose elements can be added and scaled by elements of a field.",
      "notes": "[Read concept note](./notes/Linear_Space.md)"
    },
    "Linear_Transformation": {
      "title": "Linear Transformation",
      "type": "Algebra",
      "define": "A linear transformation is a structure-preserving map between vector spaces.",
