    },
    "Manifold": {
      "title": "Manifold",
      "type": "Geometry",
      "define": "A manifold is a space that may be globally curved or complicated but locally looks like Euclidean space.",
      "notes": "[Read concept note](./notes/Manifold.md)"
    },
    "Module": {
      "title": "Module",
      "type": "Algebra",
      "define": "A module is a vector-space-like structure whose scalars come from a ring rather than necessarily from a field.",
      "notes": "[Read concept note](./notes/Module.md)"
    },
    "Normed_Linear_Space": {
      "title": "Normed Linear Space",
      "type": "Analysis",
