      "notes": "[Read concept note](./notes/Quadratic_Function.md)"
    },
    "Quaternion_Ring": {
      "title": "Quaternion Ring",
      "type": "Algebra",
      "define": "The quaternion ring extends complex numbers with three imaginary units whose multiplication is noncommutative.",
      "notes": "[Read concept note](./notes/Quaternion_Ring.md)"
    },
    "Rational_Number_Field": {
      "title": "Rational Number Field",
      "type": "Number Theory",
      "define": "The rational number field consists of ratios of integers with nonzero denominator under ordinary arithmetic.",
      "notes": "[Read concept note](./notes/Rational_Number_Field.md)"
    },
