  "nodes": {
    "Algebra_Structure": {
      "title": "Algebra Structure",
      "type": "Algebra",
      "define": "An algebraic structure is a set equipped with operations whose behavior is controlled by specified axioms.",
      "notes": "[Read concept note](./notes/Algebra_Structure.md)"
    },
    "Binary_Tree": {
      "title": "Binary Tree",
      "type": "Discrete Mathematics",
      "define": "A binary tree is a rooted tree in which each node has at most two children.",
      "notes": "[Read concept note](./notes/Binary_Tree.md)"
    },
    "Bipartite_Graph": {
      "title": "Bipartite Graph",
      "type": "Discrete Mathematics",
      "define": "A bipartite graph is a graph whose vertices can be split into two parts so that every edge connects the two parts.",
      "notes": "[Read concept note](./notes/Bipartite_Graph.md)"
    },
    "Complete_Graph": {
      "title": "Complete Graph",
      "type": "Discrete Mathematics",
      "define": "A complete graph is a graph in which every pair of distinct vertices is connected by an edge.",
      "notes": "[Read concept note](./notes/Complete_Graph.md)"
    },
    "Directed_Acyclic_Graph": {
      "title": "Directed Acyclic Graph",
      "type": "Discrete Mathematics",
      "define": "A directed acyclic graph is a directed graph with no directed cycles.",
      "notes": "[Read concept note](./notes/Directed_Acyclic_Graph.md)"
    },
    "Graph": {
      "title": "Graph",
      "type": "Discrete Mathematics",
      "define": "A graph is a structure made of vertices and edges that records pairwise relationships.",
      "notes": "[Read concept note](./notes/Graph.md)"
    },
    "Lattice": {
      "title": "Lattice",
      "type": "Discrete Mathematics",
      "define": "A lattice is an ordered set in which every pair of elements has both a greatest lower bound and a least upper bound.",
      "notes": "[Read concept note](./notes/Lattice.md)"
    },
    "Ordered_Set": {
      "title": "Ordered Set",
      "type": "Discrete Mathematics",
      "define": "An ordered set is a set where the elements can be compared to tell which comes before or after another.",
      "notes": "[Read concept note](./notes/Ordered_Set.md)"
    },
    "Set": {
      "title": "Set",
      "type": "Mathematical Logic and Foundations",
      "define": "A set is a collection of distinct objects considered as a single mathematical object.",
      "notes": "[Read concept note](./notes/Set.md)"
    },
    "Tree": {
      "title": "Tree",
      "type": "Discrete Mathematics",
      "define": "A tree is a connected acyclic graph.",
      "notes": "[Read concept note](./notes/Tree.md)"
    }
  },
