files.number-theory.json:
{
  "format": "graph-studio",
  "version": 2,
  "diagram": "dag",
  "title": "Number Theory",
  "metadata": {},
  "nodes": {
    "Automorphic_Form": {
      "title": "Automorphic Form",
      "type": "Number Theory",
      "define": "An automorphic form is a highly symmetric complex-valued function on an arithmetic quotient of a reductive group.",
      "notes": "[Read concept note](./notes/Automorphic_Form.md)"
    },
    "Dirichlet_Character": {
      "title": "Dirichlet Character",
      "type": "Number Theory",
      "define": "A Dirichlet character is a periodic multiplicative arithmetic function modulo an integer.",
      "notes": "[Read concept note](./notes/Dirichlet_Character.md)"
    },
    "Field": {
      "title": "Field",
      "type": "Algebra",
      "define": "A field is an algebraic structure where addition, subtraction, multiplication, and division by nonzero elements are all possible.",
      "notes": "[Read concept note](./notes/Field.md)"
    },
    "Function": {
      "title": "Function",
      "type": "Mathematical Logic and Foundations",
      "define": "A function assigns each input exactly one output.",
      "notes": "[Read concept note](./notes/Function.md)"
    },
    "Galois_Representation": {
      "title": "Galois Representation",
      "type": "Number Theory",
      "define": "A Galois representation is a homomorphism from a Galois group into a linear group over a coefficient field.",
      "notes": "[Read concept note](./notes/Galois_Representation.md)"
    },
    "Global_Field": {
      "title": "Global Field",
      "type": "Number Theory",
      "define": "A global field is either a number field or a function field of one variable over a finite field.",
      "notes": "[Read concept note](./notes/Global_Field.md)"
    },
    "Integer_Ring": {
      "title": "Integer Ring",
      "type": "Number Theory",
      "define": "The integer ring is the set of integers with usual addition and multiplication.",
      "notes": "[Read concept note](./notes/Integer_Ring.md)"
    },
    "L_Function": {
      "title": "L Function",
      "type": "Number Theory",
      "define": "An $L$-function is a complex analytic object that encodes arithmetic data through Euler products, Dirichlet series, and functional equations.",
      "notes": "[Read concept note](./notes/L_Function.md)"
    },
    "Local_Field": {
      "title": "Local Field",
      "type": "Number Theory",
      "define": "A local field is a field complete with respect to a nontrivial discrete valuation and having finite residue field.",
      "notes": "[Read concept note](./notes/Local_Field.md)"
    },
    "Mobius_Function": {
      "title": "Mobius Function",
      "type": "Number Theory",
      "define": "The Mobius function is an arithmetic function that records the square-free prime factor structure of an integer.",
      "notes": "[Read concept note](./notes/Mobius_Function.md)"
    },
    "Modular_Form": {
      "title": "Modular Form",
      "type": "Number Theory",
      "define": "A modular form is a holomorphic function on the upper half-plane satisfying a specific transformation law and growth condition.",
      "notes": "[Read concept note](./notes/Modular_Form.md)"
    },
    "Natural_Number": {
      "title": "Natural Number",
      "type": "Number Theory",
      "define": "Natural numbers are the discrete numbers used for counting and indexing.",
      "notes": "[Read concept note](./notes/Natural_Number.md)"
    },
    "Number_Field": {
      "title": "Number Field",
      "type": "Number Theory",
      "define": "A number field is a finite field extension of the rational numbers.",
      "notes": "[Read concept note](./notes/Number_Field.md)"
    },
    "Prime": {
      "title": "Prime",
      "type": "Number Theory",
      "define": "A prime number is a natural number greater than one whose only positive divisors are one and itself.",
      "notes": "[Read concept note](./notes/Prime.md)"
    },
    "Rational_Number_Field": {
      "title": "Rational Number Field",
      "type": "Number Theory",
      "define": "The rational number field consists of ratios of integers with nonzero denominator under ordinary arithmetic.",
      "notes": "[Read concept note](./notes/Rational_Number_Field.md)"
    },
    "Riemann_Zeta_Function": {
      "title": "Riemann Zeta Function",
      "type": "Number Theory",
      "define": "The Riemann zeta function packages the arithmetic of positive integers into a complex analytic function.",
      "notes": "[Read concept note](./notes/Riemann_Zeta_Function.md)"
    },
    "Ring": {
      "title": "Ring",
      "type": "Algebra",
      "define": "A ring is an algebraic structure with addition, subtraction, and multiplication, where multiplication need not be commutative or invertible.",
      "notes": "[Read concept note](./notes/Ring.md)"
    },
    "Set": {
      "title": "Set",
      "type": "Mathematical Logic and Foundations",
      "define": "A set is a collection of distinct objects considered as a single mathematical object.",
      "notes": "[Read concept note](./notes/Set.md)"
    },
    "p_Adic_Number": {
      "title": "p Adic Number",
      "type": "Number Theory",
      "define": "The $p$-adic numbers form the basic characteristic-zero local field attached to a prime $p$.",
      "notes": "[Read concept note](./notes/p_Adic_Number.md)"
    },
    "Complex_Valued_Function": {
      "title": "Complex Valued Function",
      "type": "Analysis",
      "define": "A complex-valued function assigns a complex number to each point of its domain.",
      "notes": "[Read concept note](./notes/Complex_Valued_Function.md)"
