      "define": "A branching process models a population in which each individual reproduces randomly and independently.",
      "notes": "[Read concept note](./notes/Branching_Process.md)"
    },
    "Brownian_Motion": {
      "title": "Brownian Motion",
      "type": "Probability Theory",
      "define": "Brownian motion is the continuous Gaussian process with stationary independent increments.",
      "notes": "[Read concept note](./notes/Brownian_Motion.md)"
    },
    "Diffusion_Process": {
      "title": "Diffusion Process",
      "type": "Probability Theory",
      "define": "A diffusion process is a Markov process with continuous sample paths.",
      "notes": "[Read concept note](./notes/Diffusion_Process.md)"
    },
    "Filtered_Probability_Space": {
      "title": "Filtered Probability Space",
      "type": "Probability Theory",
      "define": "A filtered probability space is a probability space equipped with an increasing family of sigma-algebras representing information over time.",
      "notes": "[Read concept note](./notes/Filtered_Probability_Space.md)"
    },
    "Function": {
      "title": "Function",
      "type": "Mathematical Logic and Foundations",
      "define": "A function assigns each input exactly one output.",
      "notes": "[Read concept note](./notes/Function.md)"
    },
    "Gaussian_Process": {
      "title": "Gaussian Process",
      "type": "Probability Theory",
      "define": "A Gaussian process is a stochastic process whose every finite family of coordinates is jointly Gaussian.",
      "notes": "[Read concept note](./notes/Gaussian_Process.md)"
    },
    "Levy_Process": {
      "title": "Levy Process",
      "type": "Probability Theory",
      "define": "A Levy process is a cadlag process with stationary independent increments.",
      "notes": "[Read concept note](./notes/Levy_Process.md)"
    },
    "Markov_Chain": {
      "title": "Markov Chain",
      "type": "Probability Theory",
      "define": "A Markov chain is a discrete-time Markov process.",
      "notes": "[Read concept note](./notes/Markov_Chain.md)"
    },
    "Markov_Process": {
      "title": "Markov Process",
      "type": "Probability Theory",
      "define": "A Markov process is a stochastic process whose future depends on the present state and not on the past history.",
      "notes": "[Read concept note](./notes/Markov_Process.md)"
    },
    "Martingale": {
      "title": "Martingale",
      "type": "Probability Theory",
      "define": "A martingale is a stochastic process whose conditional future value equals its present value.",
      "notes": "[Read concept note](./notes/Martingale.md)"
    },
    "Measure_Space": {
      "title": "Measure Space",
      "type": "Analysis",
      "define": "A measure space is a measurable space equipped with a measure assigning sizes to measurable sets.",
      "notes": "[Read concept note](./notes/Measure_Space.md)"
    },
    "Point_Process": {
      "title": "Point Process",
      "type": "Probability Theory",
      "define": "A point process is a random locally finite configuration of points.",
      "notes": "[Read concept note](./notes/Point_Process.md)"
    },
    "Poisson_Point_Process": {
      "title": "Poisson Point Process",
      "type": "Probability Theory",
      "define": "A Poisson point process is a point process with independent increments and constant intensity.",
      "notes": "[Read concept note](./notes/Poisson_Point_Process.md)"
    },
    "Poisson_Process": {
      "title": "Poisson Process",
      "type": "Probability Theory",
      "define": "A Poisson process is the counting process with stationary independent increments.",
      "notes": "[Read concept note](./notes/Poisson_Process.md)"
    },
    "Probability_Distribution": {
      "title": "Probability Distribution",
      "type": "Probability Theory",
      "define": "A probability distribution is the law induced by a random element on its state space.",
      "notes": "[Read concept note](./notes/Probability_Distribution.md)"
    },
    "Probability_Space": {
      "title": "Probability Space",
      "type": "Probability Theory",
      "define": "A probability space is a measure space whose total measure is one.",
      "notes": "[Read concept note](./notes/Probability_Space.md)"
    },
    "Random_Element": {
      "title": "Random Element",
      "type": "Probability Theory",
      "define": "A random element is a measurable map from a probability space into a measurable state space.",
      "notes": "[Read concept note](./notes/Random_Element.md)"
    },
    "Random_Field": {
      "title": "Random Field",
      "type": "Probability Theory",
      "define": "A random field is a stochastic process indexed by a multidimensional parameter set.",
      "notes": "[Read concept note](./notes/Random_Field.md)"
    },
    "Random_Variable": {
      "title": "Random Variable",
      "type": "Probability Theory",
      "define": "A random variable is a real-valued random element.",
      "notes": "[Read concept note](./notes/Random_Variable.md)"
    },
    "Random_Walk": {
      "title": "Random Walk",
      "type": "Probability Theory",
      "define": "A random walk is the partial-sum process of independent random increments.",
      "notes": "[Read concept note](./notes/Random_Walk.md)"
    },
    "Semimartingale": {
      "title": "Semimartingale",
      "type": "Probability Theory",
      "define": "A semimartingale is the basic integrator class for modern stochastic calculus.",
      "notes": "[Read concept note](./notes/Semimartingale.md)"
    },
    "Stationary_Process": {
      "title": "Stationary Process",
      "type": "Probability Theory",
      "define": "A stationary process is a stochastic process whose law is invariant under time shifts.",
      "notes": "[Read concept note](./notes/Stationary_Process.md)"
    },
    "Stochastic_Process": {
      "title": "Stochastic Process",
      "type": "Probability Theory",
      "define": "A stochastic process is a family of random variables indexed by time or another parameter.",
      "notes": "[Read concept note](./notes/Stochastic_Process.md)"
    },
    "Stopping_Time": {
      "title": "Stopping Time",
      "type": "Probability Theory",
      "define": "A stopping time is a random time whose occurrence can be determined from the information available up to that time.",
      "notes": "[Read concept note](./notes/Stopping_Time.md)"
    }
